INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1d8172b7-abc9-5c60-9c62-bf00cc92e183','TEXT','The Creek Sound Map','Noah liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Wednesday, Noah noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4fdf7892-f580-5c1e-b071-1662d9914660','TEXT','The Repaired Book — A Different Day','Ruby liked helping at the library corner, especially when there was a small job that nobody had planned. One Wednesday, Ruby noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
