INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a284aa49-77bc-5ed3-bfd4-bfdad38f8a70','TEXT','The Windy Sculpture','Luca liked helping at the community hall, especially when there was a small job that nobody had planned. One Friday, Luca noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('d7362c40-fd0a-5eac-8198-c5d8ca7b10e8','TEXT','A Lantern for the Jetty — A Different Day','Zoe liked helping at the sea fog, especially when there was a small job that nobody had planned. One Friday, Zoe noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
