INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('24863041-0a93-5fb1-a98f-809bbc35c374','TEXT','A Lantern for the Jetty','Zoe liked helping at the sea fog, especially when there was a small job that nobody had planned. One Saturday, Zoe noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('11a511e1-2144-5988-ae35-09f25df4d7dd','TEXT','The Seed Library — A Different Day','Eli liked helping at the community garden, especially when there was a small job that nobody had planned. One Wednesday, Eli noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
