INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('6b83b1f2-575d-5416-9424-230a7af87cab','TEXT','The Night Garden List','Mia liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Saturday, Mia noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('eacd6040-60b6-5b98-82c6-5c1b11801f13','TEXT','The Museum Window — A Different Day','Arun liked helping at the local museum, especially when there was a small job that nobody had planned. One Wednesday, Arun noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
